import * as T from 'three';
export function pneumaticGeometry(H){const {root,group,mesh,box,cyl,tor,link,tube,bolt,covers,updaters}=H,air=0x57a9af,exhaust=0xd49b64;
 const comp=group('compressor',[-1,0,0]);for(const x of [-4.5,-3.1]){box(.3,.35,.8,'steel',comp,[x,.4,-.6]);for(const z of [-.9,-.3])bolt(x,.6,z,comp)}cyl(.57,1.8,'steel',comp,[-3.8,1.13,-.6],'x');for(const x of [-4.7,-2.9]){const cap=mesh(new T.SphereGeometry(.57,28,16),'steel',comp,[x,1.13,-.6]);cap.scale.x=.24;tor(.57,.025,'dark',comp,[x,1.13,-.6]).rotation.y=Math.PI/2;}
 box(.7,.4,.65,'dark',comp,[-4,1.84,-.6]);cyl(.32,.13,'steel',comp,[-4,1.85,-.2],'z');const wheel=new T.Group();comp.add(wheel);wheel.position.set(-4,1.85,-.09);tor(.36,.055,'light',wheel,[0,0,0]);for(let j=0;j<5;j++){const a=j*Math.PI*2/5;link([0,0,0],[.32*Math.cos(a),.32*Math.sin(a),0],.025,'steel',wheel)}
 const pump=new T.Group();comp.add(pump);pump.position.set(-4,2.35,-.6);cyl(.21,.5,'steel',pump,[0,0,0]);for(let j=0;j<6;j++)tor(.24,.025,'dark',pump,[0,-.2+j*.08,0],'y');cyl(.16,.13,'dark',comp,[-4,2.72,-.6]);cyl(.13,.24,'copper',comp,[-4.35,2.66,-.6],'x');for(let j=0;j<5;j++)tor(.13,.012,'dark',comp,[-4.4+j*.035,2.66,-.6]).rotation.y=Math.PI/2;
 const pumpRod=cyl(.045,.55,'light',comp,[-4,2.02,-.6]);tube([[-3.8,2.6,-.6],[-3.5,2.6,-.6],[-3.3,2.3,-.6],[-3.3,1.69,-.6]],.04,'copper',comp);
 const regulator=group('regulator');box(.32,.4,.35,'steel',regulator,[-2.75,1.35,.2]);cyl(.13,.18,'dark',regulator,[-2.75,1.64,.2]);cyl(.18,.1,'dark',regulator,[-2.75,1.4,.44],'z');cyl(.15,.01,'light',regulator,[-2.75,1.4,.5],'z');const needle=box(.012,.12,.012,'dark',regulator,[-2.75,1.4,.52]);needle.geometry.translate(0,.04,0);tube([[-2.9,1.13,-.6],[-2.65,1.13,-.5],[-2.55,1.2,0],[-2.75,1.25,.2]],.045,'steel',regulator);
 const valve=group('valve',[0,1,0]);for(const x of [-1.85,-.25])for(const z of [.5,1.3])box(.16,.35,.16,'dark',valve,[x,.385,z]);box(2.1,.18,1.2,'steel',valve,[-1.05,.65,.9]);for(const x of [-1.9,-.2])for(const z of [.4,1.4])bolt(x,.77,z,valve);const cover=box(2,.65,1.1,'steel',valve,[-1.05,1,.9]);covers.push(cover);box(.14,.4,.9,'dark',valve,[-2.1,.95,.9]);box(.14,.4,.9,'dark',valve,[0,.95,.9]);
 const spool=group('spool',[0,1.8,0]);const spoolMoving=new T.Group();spool.add(spoolMoving);cyl(.04,2,'light',spoolMoving,[-1.05,.99,.88],'x');for(const x of [-1.65,-1.05,-.45])cyl(.105,.13,'copper',spoolMoving,[x,.99,.88],'x');box(.3,.36,.42,'dark',valve,[-2.34,.95,.9]);for(let j=0;j<7;j++){const s=tor(.1,.012,'steel',valve,[.1+j*.045,.99,.88]);s.rotation.y=Math.PI/2;}
 const ports={P:[-1.05,.9,1.55],A:[-1.55,.9,.25],B:[-.55,.9,.25],R:[-1.8,.9,1.55],S:[-.3,.9,1.55]};for(const p of Object.values(ports)){cyl(.09,.2,'copper',valve,p,'z');tor(.095,.018,'light',valve,[p[0],p[1],p[2]+(p[2]>1?.1:-.1)])}
 for(const [name,p]of Object.entries(ports)){const canvas=document.createElement('canvas');canvas.width=128;canvas.height=64;const ctx=canvas.getContext('2d');ctx.fillStyle='#e3ead7';ctx.fillRect(0,0,128,64);ctx.fillStyle='#243e32';ctx.font='bold 38px monospace';ctx.textAlign='center';ctx.fillText(({P:'1 P',A:'2 A',B:'4 B',R:'3 R',S:'5 S'})[name],64,46);const plate=new T.Mesh(new T.PlaneGeometry(.29,.145),new T.MeshBasicMaterial({map:new T.CanvasTexture(canvas),side:T.DoubleSide}));plate.rotation.x=-Math.PI/2;plate.position.set(p[0],.76,p[2]>1?1.37:.43);valve.add(plate);}
 // Working lines follow separate depth lanes; ports remain distinct and labelled in the live connection map.
 const hoses=group('hoses');const routes=[];function route(name,points,r=.055){const curve=new T.CatmullRomCurve3(points.map(p=>new T.Vector3(...p)),false,'catmullrom',.2),body=mesh(new T.TubeGeometry(curve,64,r,8,false),air,hoses);body.material.transparent=true;body.material.opacity=.52;const dots=Array.from({length:12},()=>mesh(new T.SphereGeometry(.038,8,8),0xd8f38c,hoses));routes.push({name,curve,body,dots});return body;}
 route('supply',[[-2.75,1.25,.2],[-2.8,.8,.7],[-2.65,.7,1.9],[-1.05,.7,1.9],ports.P]);
 const portA=[.45,2.2,-.05],portB=[3.55,2.2,-.05];route('A',[ports.A,[-1.55,1.05,-.35],[-1.2,1.55,-1.45],[.45,1.6,-1.45],[.45,2.2,-1.1],portA]);route('B',[ports.B,[-.55,1.05,-.2],[-.2,1.2,-1.85],[3.55,1.2,-1.85],[3.55,2.2,-1.15],portB]);
 const silencer=group('silencer');for(const [name,x]of [['R',-1.8],['S',-.3]]){route(name,[ports[name],[x,.9,1.9],[x,.95,2.2]]);cyl(.11,.27,'copper',silencer,[x,.95,2.3],'z');for(let j=0;j<5;j++)tor(.112,.009,'dark',silencer,[x,.95,2.2+j*.05]);}
 const internals=[];for(const [name,a,b]of [['PA','P','A'],['BS','B','S'],['PB','P','B'],['AR','A','R']]){const start=ports[a],end=ports[b],path=tube([start,[start[0],.82,start[2]],[end[0],.82,end[2]],end],.035,name[0]==='P'?air:exhaust,valve);internals.push({name,path})}
 const body=group('cylinder',[0,1.4,-.8]);for(const x of [.35,3.65]){box(.22,1.03,1.03,'steel',body,[x,2.2,-.5]);for(const dy of [-.39,.39])for(const dz of [-.39,.39]){const b=bolt(x+.13,2.2+dy,-.5+dz,body);b.rotation.z=Math.PI/2;}}
 const barrel=new T.Group();body.add(barrel);barrel.position.set(2,2.2,-.5);barrel.rotation.z=Math.PI/2;for(const [start,isCover]of [[Math.PI/2,false],[-Math.PI/2,true]]){const wall=mesh(new T.CylinderGeometry(.45,.45,3.08,48,1,true,start,Math.PI),'steel',barrel);wall.material.side=T.DoubleSide;if(isCover)covers.push(wall);}
 for(const dy of [-.39,.39])for(const dz of [-.39,.39])cyl(.025,3.5,'light',body,[2,2.2+dy,-.5+dz],'x');for(const x of [.35,3.65]){box(.35,1.45,.65,'steel',body,[x,1.05,-.5]);box(.65,.12,1,'dark',body,[x,.27,-.5]);}for(const p of [portA,portB]){cyl(.085,.16,'copper',body,p,'z');}
 const piston=group('piston',[0,2.4,0]),moving=new T.Group();piston.add(moving);moving.position.set(.65,2.2,-.5);cyl(.43,.16,'light',moving,[0,0,0],'x');for(const x of [-.045,.045]){const s=tor(.435,.018,'seal',moving,[x,0,0]);s.rotation.y=Math.PI/2;}cyl(.215,3.3,'light',moving,[1.73,0,0],'x');box(.25,.5,.35,'steel',moving,[3.48,0,0]);const gland=tor(.23,.065,'copper',body,[3.78,2.2,-.5]);gland.rotation.y=Math.PI/2;
 const chambers=group('chambers');const a=cyl(.415,1,air,chambers,[1,2.2,-.5],'x'),b=cyl(.415,1,exhaust,chambers,[3,2.2,-.5],'x');for(const o of [a,b]){o.material.transparent=true;o.material.opacity=.25;o.material.depthWrite=false;o.castShadow=false;}
 const chamberDots=Array.from({length:16},()=>mesh(new T.SphereGeometry(.035,8,8),air,chambers));
 updaters.push((m,e,u)=>{wheel.rotation.z=-m.compressorAngle;pumpRod.position.y=2.02+.07*Math.cos(m.compressorAngle);needle.rotation.z=1.6-(m.gaugePressure??(m.pA+m.pB))*.25;spoolMoving.position.x=m.advance?-.14:.14;const px=.65+2.7*m.x;moving.position.x=px;const lenA=px-.48,lenB=3.52-px;a.scale.y=Math.max(.01,lenA);b.scale.y=Math.max(.01,lenB);a.position.x=.4+lenA/2;b.position.x=px+.08+lenB/2;a.material.color.setHex(m.advance?air:exhaust);b.material.color.setHex(m.advance?exhaust:air);chamberDots.forEach((dot,j)=>{const left=j<8,v=((u*6+j/8)%1+1)%1;dot.position.set(left?.43+(m.advance?v:1-v)*Math.max(.01,lenA-.07):px+.12+(m.advance?v:1-v)*Math.max(.01,lenB-.07),2.2+.17*Math.sin(j*2),-.28);dot.material.color.setHex((left===m.advance)?0x4a9fa9:0xc48442);dot.visible=m.moving});chambers.visible=e<.02;hoses.visible=e<.02;internals.forEach(({name,path})=>path.visible=e<.02&&(m.advance?['PA','BS']:['PB','AR']).includes(name));for(const r of routes){const supply=r.name==='supply'||(r.name==='A'?m.advance:r.name==='B'?!m.advance:false),active=['supply','A','B',m.advance?'S':'R'].includes(r.name);r.body.material.color.setHex(supply?air:exhaust);r.body.material.opacity=active?.65:.18;const direction=r.name==='A'?(m.advance?1:-1):r.name==='B'?(m.advance?-1:1):1;for(let i=0;i<r.dots.length;i++){const v=((direction*u*6+i/12)%1+1)%1;r.dots[i].position.copy(r.curve.getPointAt(v));r.dots[i].material.color.setHex(supply?0xd9f3a1:0xf3c897);r.dots[i].visible=m.moving&&active&&e<.02;}}});
}
